effect.shader:
void main(){
    vec2 ctr = center/1000.0 + 0.5;
    vec2 d = acScreenNorm - ctr;
    float r = length(d);
    float z = abs(fract(r*freq - acTime*speed)*2.0 - 1.0) - 0.5;
    vec2 uv = acScreenNorm + normalize(d+0.0001)*z*amount*0.08;
    gl_FragColor = texture2DCv(inputImg.texture, uv);
}
